#include <cassert>
#include <iostream>
#include <memory>
#include <new>
#include <queue>
#include <unordered_map>
#include <unordered_set>
#include <vector>

struct Node {
    static int alive;
    static int creationBudget;  // 검증용: 0이면 생성 중 예외를 흉내 냅니다.
    int value;
    std::vector<Node*> edges;  // 소유하지 않는 연결: 수명은 Graph가 관리합니다.
    explicit Node(int v) : value(v) {
        if (creationBudget == 0) throw std::bad_alloc();
        if (creationBudget > 0) --creationBudget;
        ++alive;
    }
    ~Node() { --alive; }
};
int Node::alive = 0;
int Node::creationBudget = -1;
struct Graph {
    std::vector<std::unique_ptr<Node>> nodes;
    Node* root = nullptr;
};

Graph cloneReachable(const Node* root) {
    Graph result;
    std::unordered_map<const Node*, Node*> copied;
    std::queue<const Node*> pending;
    const auto ensure = [&](const Node* old) -> Node* {
        if (!old) return nullptr;
        const auto found = copied.find(old);
        if (found != copied.end()) return found->second;
        // 먼저 소유권을 확보하고 원본→복사본 대응을 기록합니다.
        result.nodes.push_back(std::unique_ptr<Node>(new Node(old->value)));
        Node* fresh = result.nodes.back().get();
        copied.emplace(old, fresh);
        pending.push(old);
        return fresh;
    };
    result.root = ensure(root);
    while (!pending.empty()) {
        const Node* old = pending.front();
        pending.pop();
        Node* fresh = copied.at(old);
        for (const Node* next : old->edges) fresh->edges.push_back(ensure(next));
    }
    // 예외가 나면 지역 result의 unique_ptr들이 만든 노드를 모두 회수합니다.
    return result;
}

std::size_t verify(const Node* source, const Graph& copy) {
    if (!source) { assert(copy.root == nullptr && copy.nodes.empty()); return 0; }
    std::unordered_map<const Node*, const Node*> pair;
    std::unordered_set<const Node*> used;
    std::queue<const Node*> q;
    pair[source] = copy.root;
    used.insert(copy.root);
    q.push(source);
    while (!q.empty()) {
        const Node* a = q.front(); q.pop();
        const Node* b = pair.at(a);
        assert(a != b && a->value == b->value && a->edges.size() == b->edges.size());
        for (std::size_t i = 0; i < a->edges.size(); ++i) {
            const Node* x = a->edges[i];
            const Node* y = b->edges[i];
            if (!x) { assert(!y); continue; }
            assert(y);
            const auto found = pair.find(x);
            if (found == pair.end()) {
                assert(used.insert(y).second);  // 다른 원본을 같은 복사본에 합치지 않습니다.
                pair[x] = y; q.push(x);
            } else assert(found->second == y); // 원본의 공유 연결은 그대로 공유합니다.
        }
    }
    assert(pair.size() == copy.nodes.size());
    for (const auto& a : pair) for (const auto& b : pair) assert(a.first != b.second);
    return pair.size();
}
int main() {
    long long graphs = 0, failures = 0;
    verify(nullptr, cloneReachable(nullptr));
    for (unsigned mask = 0; mask < 512; ++mask) {
        Graph source;
        for (int i = 0; i < 3; ++i) source.nodes.push_back(std::unique_ptr<Node>(new Node(7)));
        source.root = source.nodes[0].get();
        for (int i = 0; i < 3; ++i) for (int j = 0; j < 3; ++j)
            if (mask & (1u << (3 * i + j))) source.nodes[i]->edges.push_back(source.nodes[j].get());
        std::size_t reachable = 0;
        {
            Graph copy = cloneReachable(source.root);
            reachable = verify(source.root, copy);
            copy.root->value = 99;
            assert(source.root->value == 7);
        }
        const int baseline = Node::alive;
        for (std::size_t limit = 0; limit < reachable; ++limit) {
            Node::creationBudget = static_cast<int>(limit);
            bool threw = false;
            try { Graph copy = cloneReachable(source.root); }
            catch (const std::bad_alloc&) { threw = true; }
            Node::creationBudget = -1;
            assert(threw && Node::alive == baseline);
            ++failures;
        }
        ++graphs;
    }
    {
        Graph source;
        source.nodes.push_back(std::unique_ptr<Node>(new Node(1)));
        source.nodes.push_back(std::unique_ptr<Node>(new Node(2)));
        source.root = source.nodes[0].get();
        source.root->edges = {source.nodes[1].get(), source.nodes[1].get(), nullptr};
        source.nodes[1]->edges = {source.root, source.nodes[1].get()};
        Graph copy = cloneReachable(source.root);
        verify(source.root, copy);
    }
    assert(Node::alive == 0);
    std::cout << "graphs " << graphs << "; injected constructor failures " << failures
              << "; null/parallel edges/self-cycle and cleanup passed\n";
}
